#include <stdlib.h>
#include <string.h>

int main(int argc, char** argv){
  if(argc<2) return 1;
  FILE* f=fopen(argv[1],"rb"); if(!f) return 1;
  fseek(f,0,SEEK_END); long sz=ftell(f); rewind(f);
  unsigned char* buf=malloc(sz); fread(buf,1,sz,f); fclose(f);
  FT_Library lib; FT_Init_FreeType(&lib);
  size_t vsize=sizeof(FT_Vector), tsize=sizeof(char);
  short n_points=(short)(sz/(vsize+tsize));
  if(n_points<=2) return 0;
  FT_Vector* points=(FT_Vector*)buf;
  char* tags=(char*)(buf + (size_t)n_points*vsize);
  for(short i=0;i<n_points;i++){ points[i].x = (points[i].x<0)?-( -points[i].x & 0xFFFFFF)-1:(points[i].x & 0xFFFFFF)+1; points[i].y = (points[i].y<0)?-( -points[i].y & 0xFFFFFF)-1:(points[i].y & 0xFFFFFF)+1; }
  short contours[1]; contours[0]=n_points-1;
  FT_Outline outline={1,n_points,points,tags,contours,FT_OUTLINE_NONE};
  unsigned char pixels[4];
  FT_Bitmap bm={1,1,4,pixels,2,FT_PIXEL_MODE_MONO,0,NULL};
  FT_Outline_Get_Bitmap(lib,&outline,&bm);
  FT_Done_FreeType(lib);
  return 0;
}
''')
